begin;
alter table public.nexus_city_placements add column if not exists footprint_w smallint not null default 1 check(footprint_w between 1 and 20);alter table public.nexus_city_placements add column if not exists footprint_h smallint not null default 1 check(footprint_h between 1 and 20);alter table public.nexus_city_placements add column if not exists request_id uuid;
create unique index if not exists nexus_city_placement_request_unique on public.nexus_city_placements(city_id,request_id) where request_id is not null;
create table if not exists public.nexus_city_asset_slots(city_id uuid not null references public.nexus_cities(city_id) on delete cascade,asset_code text not null references public.nexus_city_assets(code),slot_no integer not null check(slot_no between 1 and 100),item_instance_id uuid references public.item_instances(id) on delete set null,updated_at timestamptz not null default now(),primary key(city_id,asset_code,slot_no),unique(city_id,item_instance_id));
alter table public.nexus_city_asset_slots enable row level security;revoke all on public.nexus_city_asset_slots from public,anon,authenticated;grant select on public.nexus_city_asset_slots to authenticated;grant all on public.nexus_city_asset_slots to service_role;create policy nexus_city_asset_slots_read on public.nexus_city_asset_slots for select to authenticated using(exists(select 1 from public.nexus_cities c where c.city_id=nexus_city_asset_slots.city_id and (c.user_id=(select auth.uid()) or c.visibility='public')));
create or replace function public.nexus_city_place_v2(p_user uuid,p_building text,p_x integer,p_z integer,p_rotation smallint,p_request uuid) returns uuid language plpgsql security invoker set search_path='' as $$declare c public.nexus_cities;b public.nexus_city_buildings;pid uuid;member_xp bigint;member_points bigint;lvl integer;fw integer;fh integer;half integer;count_build integer;begin if p_request is null then raise exception 'Identifiant de construction requis';end if;select * into c from public.nexus_cities where user_id=p_user for update;if not found then raise exception 'Crée ta ville 3B d abord';end if;select id into pid from public.nexus_city_placements where city_id=c.city_id and request_id=p_request;if pid is not null then return pid;end if;select count(*) into count_build from public.nexus_city_placements where city_id=c.city_id;if count_build>=least(500,50+c.land_tier*45) then raise exception 'Limite de constructions atteinte pour ce terrain';end if;select * into b from public.nexus_city_buildings where code=p_building and active=true;if not found then raise exception 'Bâtiment indisponible';end if;select xp,points into member_xp,member_points from public.member_profiles where user_id=p_user for update;lvl=greatest(1,least(100,(member_xp/1000)::integer+1));if lvl<b.unlock_level then raise exception 'Niveau insuffisant';end if;if b.country is not null and not exists(select 1 from public.nexus_city_districts where city_id=c.city_id and country=b.country and unlocked=true) then raise exception 'Quartier non débloqué';end if;fw=greatest(1,least(20,coalesce((b.footprint->>'w')::integer,1)));fh=greatest(1,least(20,coalesce((b.footprint->>'h')::integer,1)));if p_rotation in (90,270) then select fh,fw into fw,fh;end if;half=50+c.land_tier*45;if p_x< -half or p_z< -half or p_x+fw-1>half or p_z+fh-1>half then raise exception 'Construction hors du terrain';end if;if exists(select 1 from public.nexus_city_placements q where q.city_id=c.city_id and p_x<=q.x+q.footprint_w-1 and p_x+fw-1>=q.x and p_z<=q.z+q.footprint_h-1 and p_z+fh-1>=q.z) then raise exception 'Cette parcelle est déjà occupée';end if;if b.cost_coins>0 and member_points<b.cost_coins then raise exception 'Coins 3B insuffisants';end if;if b.cost_coins>0 then update public.member_profiles set points=points-b.cost_coins where user_id=p_user;insert into public.member_ledger(user_id,event_key,source,label,xp,points) values(p_user,p_user||':city:build:'||p_request,'city','Construction Ville 3B · '||b.name,0,-b.cost_coins::integer) on conflict(event_key) do nothing;if not found then raise exception 'Construction déjà traitée';end if;end if;insert into public.nexus_city_placements(city_id,building_code,x,z,rotation,footprint_w,footprint_h,request_id) values(c.city_id,b.code,p_x,p_z,p_rotation,fw,fh,p_request) returning id into pid;insert into public.nexus_city_unlocks(city_id,building_code,source) values(c.city_id,b.code,'level') on conflict do nothing;insert into public.nexus_city_journal(city_id,user_id,action,reference_id,coins,metadata) values(c.city_id,p_user,'build',pid,-b.cost_coins,jsonb_build_object('building',b.code,'x',p_x,'z',p_z));update public.nexus_cities set revision=revision+1,updated_at=now() where city_id=c.city_id;return pid;end;$$;
create or replace function public.nexus_city_asset_set(p_user uuid,p_asset text,p_slot integer,p_item uuid) returns boolean language plpgsql security invoker set search_path='' as $$declare c public.nexus_cities;a public.nexus_city_assets;i public.item_instances;d public.inventory_items;begin select * into c from public.nexus_cities where user_id=p_user for update;if not found then raise exception 'Ville introuvable';end if;select * into a from public.nexus_city_assets where code=p_asset and active=true;if not found or p_slot<1 or p_slot>a.capacity then raise exception 'Emplacement invalide';end if;if c.city_level<a.unlock_level then raise exception 'Niveau de ville insuffisant';end if;if p_item is null then delete from public.nexus_city_asset_slots where city_id=c.city_id and asset_code=p_asset and slot_no=p_slot;return true;end if;select * into i from public.item_instances where id=p_item and owner_id=p_user and state='owned';if not found then raise exception 'Objet non possédé';end if;select * into d from public.inventory_items where code=i.item_code;if a.required_item_type is not null and d.item_type<>a.required_item_type then raise exception 'Type d objet incompatible';end if;if a.required_rarity is not null and d.rarity<>a.required_rarity then raise exception 'Rareté incompatible';end if;insert into public.nexus_city_asset_slots(city_id,asset_code,slot_no,item_instance_id) values(c.city_id,p_asset,p_slot,p_item) on conflict(city_id,asset_code,slot_no) do update set item_instance_id=excluded.item_instance_id,updated_at=now();return true;end;$$;
create or replace function public.nexus_city_can_view(p_viewer uuid,p_city uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from public.nexus_cities c where c.city_id=p_city and (c.user_id=p_viewer or c.visibility='public' or (c.visibility='friends' and exists(select 1 from public.community_follows a join public.community_follows b on b.user_id=a.target_id and b.target_id=a.user_id where a.user_id=p_viewer and a.target_id=c.user_id))));$$;
revoke all on function public.nexus_city_place_v2(uuid,text,integer,integer,smallint,uuid),public.nexus_city_asset_set(uuid,text,integer,uuid),public.nexus_city_can_view(uuid,uuid) from public,anon,authenticated;grant execute on function public.nexus_city_place_v2(uuid,text,integer,integer,smallint,uuid),public.nexus_city_asset_set(uuid,text,integer,uuid),public.nexus_city_can_view(uuid,uuid) to service_role;
commit;
